events=[]
class Keyword(str):
    def __hash__(self): return 17
    def __eq__(self, other):
        events.append(('eq',str.__str__(self),other))
        raise AssertionError('keyword equality')
    def __str__(self):
        events.append('keyword-str')
        raise AssertionError('keyword str')
    def __iter__(self): raise AssertionError('keyword iter')
    def __len__(self): raise AssertionError('keyword len')
class Stream:
    def __getattribute__(self, name):
        events.append(('lookup',name))
        return object.__getattribute__(self,name)
    def write(self, text):
        events.append(('write',text,type(text).__name__))
    def flush(self): events.append('flush')
class Flag:
    def __bool__(self):
        events.append('truth')
        return True
class Text(str):
    def __str__(self):
        events.append('text-str')
        return 'converted'
stream=Stream()
flag=Flag()
try:
    value=print('a','b',file=stream,**{Keyword('sep'):Text('|')})
    result=('ok',value)
except BaseException as error:
    result=('exception',type(error).__name__,str(error),error.args)
result=(result,events)

